package com.company.skillplatform.bundle.application;
import com.company.skillplatform.artifact.infrastructure.entity.SkillArtifactEntity;import com.company.skillplatform.artifact.infrastructure.repository.SkillArtifactRepository;import com.company.skillplatform.bundle.infrastructure.entity.*;import com.company.skillplatform.bundle.infrastructure.repository.*;import com.company.skillplatform.common.application.BusinessException;import com.company.skillplatform.compatibility.infrastructure.entity.PlatformEntity;import com.company.skillplatform.compatibility.infrastructure.repository.PlatformRepository;import com.company.skillplatform.dependency.application.DependencyService;import com.company.skillplatform.storage.domain.ObjectStoragePort;import com.company.skillplatform.user.infrastructure.repository.IamUserRepository;import com.company.skillplatform.version.domain.LifecycleStatus;import com.company.skillplatform.version.infrastructure.entity.SkillVersionEntity;import com.company.skillplatform.version.infrastructure.repository.SkillVersionRepository;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Instant;import java.util.*;import java.util.zip.*;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class BundleService{
 private static final int MAX_ROOTS=50;private final SkillBundleRepository bundles;private final SkillBundleItemRepository items;private final PlatformRepository platforms;private final IamUserRepository users;private final SkillVersionRepository versions;private final DependencyService deps;private final SkillArtifactRepository artifacts;private final ObjectStoragePort storage;public BundleService(SkillBundleRepository b,SkillBundleItemRepository i,PlatformRepository p,IamUserRepository u,SkillVersionRepository v,DependencyService d,SkillArtifactRepository a,ObjectStoragePort s){bundles=b;items=i;platforms=p;users=u;versions=v;deps=d;artifacts=a;storage=s;}
 @PreAuthorize("hasAuthority('skill:download')")@Transactional public BundleView create(CreateCommand c,Long actorId){validate(c);String platformKey=c.platform().toUpperCase(Locale.ROOT),requestedOs=c.osType().toUpperCase(Locale.ROOT);PlatformEntity platform=platforms.findByPlatformKey(platformKey).filter(p->"ACTIVE".equals(p.getStatus())).orElseThrow(()->error("PLATFORM_NOT_AVAILABLE","Platform does not exist or is disabled",HttpStatus.UNPROCESSABLE_ENTITY));LinkedHashMap<Long,Selection> selected=new LinkedHashMap<>();for(Long rootId:c.rootVersionIds()){SkillVersionEntity root=published(rootId);merge(selected,root,0,root.getSkill().getSkillKey(),true);if(c.includeDependencies()){DependencyService.ResolveView resolved=deps.resolve(rootId);if(!resolved.conflicts().isEmpty())throw error("BUNDLE_DEPENDENCY_CONFLICT",String.join("; ",resolved.conflicts()),HttpStatus.UNPROCESSABLE_ENTITY);for(var resolvedItem:resolved.items()){SkillVersionEntity dependency=versions.findAll().stream().filter(v->resolvedItem.skillKey().equals(v.getSkill().getSkillKey())&&resolvedItem.version().equals(v.getVersion())).findFirst().orElseThrow(()->error("BUNDLE_RESOLVED_VERSION_NOT_FOUND","Resolved dependency not found: "+resolvedItem.skillKey(),HttpStatus.UNPROCESSABLE_ENTITY));merge(selected,dependency,resolvedItem.depth(),resolvedItem.requiredByPath(),false);}}}String lock=hash(selected.keySet().toString()+platformKey+requestedOs);String key=hash(actorId+"|"+lock+"|bundle-v2");var old=bundles.findByBundleKey(key);if(old.isPresent())return view(old.get(),items.findByBundleId(old.get().getId()));SkillBundleEntity bundle=bundles.save(new SkillBundleEntity(key,platform,requestedOs,c.includeDependencies(),lock,users.findById(actorId).orElseThrow()));try{ByteArrayOutputStream output=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(output)){for(Selection selection:selected.values()){SkillArtifactEntity artifact=artifact(selection.version(),platformKey,requestedOs);zip.putNextEntry(new ZipEntry(selection.version().getSkill().getSkillKey()+"/"+artifact.getFileName()));try(InputStream input=storage.get(artifact.getObjectKey())){input.transferTo(zip);}zip.closeEntry();items.save(new SkillBundleItemEntity(bundle,selection.version(),artifact,selection.root(),selection.depth(),String.join(" | ",selection.paths())));}}byte[] bytes=output.toByteArray();String object="bundles/"+key+".zip";storage.put(object,new ByteArrayInputStream(bytes),bytes.length,"application/zip");bundle.available(object,bytes.length,hashBytes(bytes));bundles.save(bundle);return view(bundle,items.findByBundleId(bundle.getId()));}catch(IOException ex){throw error("BUNDLE_BUILD_FAILED","Unable to build bundle",HttpStatus.UNPROCESSABLE_ENTITY);}}
 @PreAuthorize("hasAuthority('skill:download')")@Transactional(readOnly=true)public Page<BundleView> list(Long actorId,Pageable pageable){return bundles.findByCreatedById(actorId,pageable).map(b->view(b,items.findByBundleId(b.getId())));}
 @PreAuthorize("hasAuthority('skill:download')")@Transactional(readOnly=true)public BundleView get(Long id,Long actorId){SkillBundleEntity b=owned(id,actorId);return view(b,items.findByBundleId(id));}
 @PreAuthorize("hasAuthority('skill:download')")@Transactional(readOnly=true)public List<BundleItemView> items(Long id,Long actorId){owned(id,actorId);return items.findByBundleId(id).stream().map(this::itemView).toList();}
 @Transactional public void retryBuild(Long id){SkillBundleEntity b=bundles.findById(id).orElseThrow(()->error("BUNDLE_NOT_FOUND","Bundle not found",HttpStatus.NOT_FOUND));try{ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(out)){for(SkillBundleItemEntity item:items.findByBundleId(id)){SkillArtifactEntity a=item.getArtifact();zip.putNextEntry(new ZipEntry(item.getVersion().getSkill().getSkillKey()+"/"+a.getFileName()));try(InputStream in=storage.get(a.getObjectKey())){in.transferTo(zip);}zip.closeEntry();}}byte[] bytes=out.toByteArray();String object="bundles/"+b.getBundleKey()+".zip";storage.put(object,new ByteArrayInputStream(bytes),bytes.length,"application/zip");b.available(object,bytes.length,hashBytes(bytes));bundles.save(b);}catch(Exception ex){String message=ex.getMessage()==null?"Bundle retry failed":ex.getMessage();b.failed("BUNDLE_RETRY_FAILED",message.substring(0,Math.min(1024,message.length())));bundles.save(b);}}
 private void validate(CreateCommand c){if(c.rootVersionIds()==null||c.rootVersionIds().isEmpty())throw error("BUNDLE_ROOTS_REQUIRED","At least one root version is required",HttpStatus.BAD_REQUEST);if(c.rootVersionIds().size()>MAX_ROOTS)throw error("BUNDLE_ROOT_LIMIT_EXCEEDED","At most 50 root versions are allowed",HttpStatus.BAD_REQUEST);if(new HashSet<>(c.rootVersionIds()).size()!=c.rootVersionIds().size())throw error("BUNDLE_DUPLICATE_ROOT","Root version IDs must be unique",HttpStatus.BAD_REQUEST);}
 private void merge(Map<Long,Selection> selected,SkillVersionEntity version,int depth,String path,boolean root){Selection old=selected.get(version.getId());if(old==null){LinkedHashSet<String> paths=new LinkedHashSet<>();paths.add(path);selected.put(version.getId(),new Selection(version,depth,paths,root));}else{old.paths().add(path);selected.put(version.getId(),new Selection(version,Math.min(old.depth(),depth),old.paths(),old.root()||root));}}
 private SkillArtifactEntity artifact(SkillVersionEntity version,String platform,String requestedOs){return artifacts.findFirstByVersionIdAndPlatformPlatformKeyAndOsTypeAndStatus(version.getId(),platform,requestedOs,"AVAILABLE").or(()->"ANY".equals(requestedOs)?Optional.empty():artifacts.findFirstByVersionIdAndPlatformPlatformKeyAndOsTypeAndStatus(version.getId(),platform,"ANY","AVAILABLE")).orElseThrow(()->error("BUNDLE_ARTIFACT_NOT_FOUND","Artifact missing for skill="+version.getSkill().getSkillKey()+", platform="+platform+", osType="+requestedOs,HttpStatus.UNPROCESSABLE_ENTITY));}
 private SkillBundleEntity owned(Long id,Long actorId){return bundles.findByIdAndCreatedById(id,actorId).orElseThrow(()->error("BUNDLE_NOT_FOUND","Bundle not found",HttpStatus.NOT_FOUND));}private SkillVersionEntity published(Long id){SkillVersionEntity v=versions.findById(id).orElseThrow(()->error("SKILL_VERSION_NOT_FOUND","Skill version not found",HttpStatus.NOT_FOUND));if(v.getVersion()==null||!(v.getLifecycleStatus()==LifecycleStatus.PUBLISHED||v.getLifecycleStatus()==LifecycleStatus.DEPRECATED))throw error("BUNDLE_VERSION_NOT_DOWNLOADABLE","Root version is not published or deprecated",HttpStatus.UNPROCESSABLE_ENTITY);return v;}private String hash(String s){return hashBytes(s.getBytes(StandardCharsets.UTF_8));}private String hashBytes(byte[] b){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(Exception e){throw new IllegalStateException(e);}}private BusinessException error(String code,String message,HttpStatus status){return new BusinessException(code,message,status);}private BundleItemView itemView(SkillBundleItemEntity i){return new BundleItemView(i.getVersion().getSkill().getSkillKey(),i.getVersion().getId(),i.getVersion().getVersion(),i.isRootSelected(),i.getDependencyDepth(),List.of(i.getRequiredByPath().split(" \\| ")),i.getArtifact().getId(),i.getArtifact().getOsType());}private BundleView view(SkillBundleEntity b,List<SkillBundleItemEntity> rows){return new BundleView(b.getId(),b.getBundleKey(),b.getStatus(),b.getPlatform().getPlatformKey(),b.getOsType(),b.isIncludeDependencies(),b.getFileName(),b.getSizeBytes(),b.getSha256(),b.getErrorCode(),b.getErrorMessage(),b.getTimeCreated(),rows.stream().map(this::itemView).toList());}
 private record Selection(SkillVersionEntity version,int depth,LinkedHashSet<String> paths,boolean root){}public record CreateCommand(String platform,String osType,List<Long> rootVersionIds,boolean includeDependencies){}public record BundleItemView(String skillKey,Long versionId,String version,boolean root,int depth,List<String> requiredByPaths,Long artifactId,String artifactOsType){}public record BundleView(Long id,String bundleKey,String status,String platform,String osType,boolean includeDependencies,String fileName,Long sizeBytes,String sha256,String errorCode,String errorMessage,Instant createdAt,List<BundleItemView> items){}
}
